def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    paths = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                path = [(r, c), (r, c + 1), (r, c + 2), (r - 1, c + 2)]
            elif color == 2:
                path = [(r, c - i) for i in range(5)]
            elif color == 3:
                path = [(r + i, c) for i in range(4)]
            elif color == 6:
                path = [(r - i, c) for i in range(7)]
            else:
                continue

            paths.append((color, path))
            for i, (rr, cc) in enumerate(path):
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = color if i in (0, len(path) - 1) else 5

    horizontal_twos = [set(path) for color, path in paths if color == 2]
    verticals = [set(path) for color, path in paths if color in (3, 6)]

    for horizontal in horizontal_twos:
        for vertical in verticals:
            for rr, cc in horizontal & vertical:
                out[rr][cc] = 4
                k = 1
                while rr + k < h and cc - k >= 0:
                    out[rr + k][cc - k] = 4
                    k += 1

    return out
